// TestEvictionSuppressionPlayJoint — eviction task 5.1, the churn-killer
// joint (Tier 1): the orchestrator policy, the sweep composition, the enrich
// lanes, and the real pack lane in one harness. The round trip is the
// production guarantee end to end:
//
//  1. an episode packs through the REAL lane (the frontier fronts the pilot,
//     the queue runs stream.Service.Pack — real ffmpeg — and publishes);
//  2. the budget sweep evicts that document-named build (the budget sits one
//     byte below the build, the pin cap three fifths of that, so the built
//     position breaks the working-set prefix) and marks the suppression set;
//  3. the NEXT sweep enqueues nothing — the frontier consults the mark (no
//     job, no pin, no bytes) and the integrity pass stays silent too. The
//     control snapshot — the same input without the mark — fronts the pilot
//     again, so only the suppression explains the silence;
//  4. a POST /play re-arms the item BEFORE the pack decision and dispatches
//     through the preferred lane while the shared buffer is saturated
//     (drop-on-full refused, urgent accepted) — the worker takes the urgent
//     task ahead of the buffered background work and the FRESH build
//     publishes under a new nonce; the descriptor answers hls again.
//
// The mirrored cmd/mellifera shell lives in eviction_shell_test.go.
package itest

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/access"
	"github.com/mellifera/mellifera/internal/api"
	"github.com/mellifera/mellifera/internal/pack"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/internal/stream"
)

// TestEvictionSuppressionPlayJoint is the acceptance joint for the whole
// eviction change (task 5.1): evict → suppressed → play → repacked. See the
// file comment for the four legs. Assertions are synchronous wherever the
// composition is synchronous (the sweeps decide and execute inline); every
// async wait is a bounded poll on real state, never a sleep.
func TestEvictionSuppressionPlayJoint(t *testing.T) {
	w := pbNewWorld(t) // skips itself when ffmpeg/ffprobe are absent
	ctx := context.Background()

	// The pack seam: the played item's packs run the REAL pack lane
	// (stream.Service.Pack — real ffmpeg); every background saturator parks
	// on a gate the test owns (the TestStreamsJoint long-run technique), so
	// the shared buffer holds saturated work while the play's urgent
	// dispatch lands and the fresh build still runs for real.
	gate := make(chan struct{})
	var gateOnce sync.Once
	openGate := func() { gateOnce.Do(func() { close(gate) }) }
	t.Cleanup(openGate) // registered after pbNewQueue's Stop: opens BEFORE the drain
	var epID string
	var packMu sync.Mutex
	var packStarted []string // the pack seam's entry log (dispatch reached a worker)
	packFn := func(ctx context.Context, itemID, absPath string, ff map[string]any, vo []string) (pack.PackOutcome, error) {
		packMu.Lock()
		packStarted = append(packStarted, itemID)
		packMu.Unlock()
		defer func() {
			packMu.Lock()
			packStarted = append(packStarted, itemID+"/done")
			packMu.Unlock()
		}()
		if itemID == epID {
			build, err := w.media.Pack(ctx, itemID, absPath, ff, vo)
			return pack.PackOutcome{Playlist: build.Playlist, Nonce: build.Nonce}, err
		}
		<-gate
		return pack.PackOutcome{Playlist: "index.m3u8", Nonce: "n-" + itemID}, nil
	}
	q := w.pbNewQueue(t, packFn, 0)

	// The recorder wraps the REAL shared-lane seam (the sweep's enqueue): it
	// observes every dispatch the sweeps attempt without replacing the lane.
	var recMu sync.Mutex
	var recorded []string
	sweepEnqueue := func(itemID string) error {
		recMu.Lock()
		recorded = append(recorded, itemID)
		recMu.Unlock()
		return q.EnqueuePack(itemID)
	}
	recordedNow := func() []string {
		recMu.Lock()
		defer recMu.Unlock()
		return append([]string(nil), recorded...)
	}

	// The serial fixture: one streams-enabled SERIAL-module library — the
	// serial module binds serial-scanner (structure series-directories), the
	// only lane that persists series rows; the tv module binds base-scanner,
	// which has no series concept (registry.go). The real scan persists the
	// series row, the episode row, and the real ffprobe facts the pack gate
	// judges.
	libRoot := t.TempDir()
	if err := os.MkdirAll(filepath.Join(libRoot, "Churn_Peak"), 0o755); err != nil {
		t.Fatalf("mkdir serial dir: %v", err)
	}
	epRel := filepath.Join("Churn_Peak", "Churn Peak S01E01.mkv")
	pbMakeMKV(t, filepath.Join(libRoot, epRel), 5*time.Second, false)
	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Eviction Churn")
	pbScanLibrary(t, w, libID)
	pbAwaitIdle(t, q, 60*time.Second)
	items := pbItemByRel(t, w, libID)
	if len(items) != 1 {
		t.Fatalf("serial scan persisted %d items, want exactly the one episode: %v", len(items), items)
	}
	for _, it := range items {
		epID = it.ID
	}
	sup := newEvSuppression()

	// Leg 1 — the pack through the real lane. The unbuilt position carries
	// zero build bytes and pins under any positive cap, so this pass's
	// frontier decision is the same one the post-pack budget produces.
	jobs1, _ := evSweep(ctx, w.st, w.media, w.root, sweepEnqueue, 1<<30, sup)
	if len(jobs1) != 1 || jobs1[0].ItemID != epID || jobs1[0].Reason != "pilot" {
		t.Fatalf("frontier jobs = %+v, want exactly the pilot job for %s", jobs1, epID)
	}
	if got := recordedNow(); len(got) != 1 || got[0] != epID {
		t.Fatalf("lane dispatches = %v, want exactly [%s]", got, epID)
	}
	streams1 := pbAwaitStreams(t, w.st, epID, stream.StateComplete, 90*time.Second)
	nonce1, _ := streams1["nonce"].(string)
	if nonce1 == "" {
		t.Fatalf("packed build missing nonce: %v", streams1)
	}
	pbAwaitIdle(t, q, 60*time.Second)
	build1 := filepath.Join(w.root, epID, nonce1)
	sizeB := evDirSize(build1)
	if sizeB <= 1 {
		t.Fatalf("build size = %d bytes, want a real packed build", sizeB)
	}

	// Leg 2 — the budget sweep evicts the document-named build. budget=B-1
	// (the unit seam's forcing trick): the pin cap 3(B-1)/5 is below B, so
	// the built position breaks the working-set prefix, joins no pin, and
	// the policy takes the only build on disk.
	budget := sizeB - 1
	jobs2, fronted2 := evSweep(ctx, w.st, w.media, w.root, sweepEnqueue, budget, sup)
	if len(jobs2) != 0 {
		t.Fatalf("the built position fronted during the eviction pass: %+v", jobs2)
	}
	if fronted2[epID] {
		t.Fatalf("the built position pinned despite overflowing the cap: %v", fronted2)
	}
	if _, err := os.Stat(build1); !os.IsNotExist(err) {
		t.Fatalf("document-named build survived the budget sweep: %v", err)
	}
	row2, err := w.st.GetItem(ctx, epID, access.System())
	if err != nil {
		t.Fatalf("GetItem after eviction: %v", err)
	}
	streams2, _ := evDecodeDoc(row2.Document)["streams"].(map[string]any)
	if streams2["state"] != stream.StateNone {
		t.Fatalf("streams state after eviction = %v, want none (the record must stop advertising a gone build)", streams2)
	}
	if _, kept := streams2["nonce"]; kept {
		t.Fatalf("the reset kept the evicted nonce: %v", streams2)
	}
	if !sup.contains(epID) {
		t.Fatal("the budget eviction of the named build never marked the suppression set")
	}
	if got := recordedNow(); len(got) != 1 {
		t.Fatalf("lane dispatches after the eviction pass = %v, want still exactly one — no re-front before the mark", got)
	}

	// Leg 3 — the churn stays dead. The suppression holds the frontier (no
	// job, no pin, no bytes) and the integrity pass stays silent; nothing
	// re-arms the item but a play. The control snapshot — the same input
	// WITHOUT the mark — fronts the pilot again, so only the suppression
	// explains the silence.
	jobs3, fronted3 := evSweep(ctx, w.st, w.media, w.root, sweepEnqueue, budget, sup)
	if len(jobs3) != 0 {
		t.Fatalf("suppressed position fronted: %+v", jobs3)
	}
	if fronted3[epID] {
		t.Fatalf("suppressed position pinned: %v", fronted3)
	}
	if got := recordedNow(); len(got) != 1 {
		t.Fatalf("suppressed sweeps re-enqueued: %v, want silence — the churn stays dead", got)
	}
	row3, err := w.st.GetItem(ctx, epID, access.System())
	if err != nil {
		t.Fatalf("GetItem after suppressed sweep: %v", err)
	}
	streams3, _ := evDecodeDoc(row3.Document)["streams"].(map[string]any)
	if streams3["state"] != stream.StateNone {
		t.Fatalf("streams state drifted to %v under suppression", streams3)
	}
	if _, err := os.Stat(build1); !os.IsNotExist(err) {
		t.Fatalf("the suppressed sweep rebuilt the evicted build: %v", err)
	}
	control, err := evFrontierJobs(ctx, w.st, w.root, budget, nil)
	if err != nil {
		t.Fatalf("control frontier: %v", err)
	}
	if len(control) != 1 || control[0].ItemID != epID {
		t.Fatalf("control jobs = %+v, want exactly the frontable pilot — the silence must be the suppression, not a broken fixture", control)
	}

	// Leg 4 — the play re-arms through the preferred lane under saturation.
	// Fill the shared buffer until the drop-on-full refusal answers, prove
	// the sweep's plain seam is honestly refused in that state, then POST
	// /play: the re-arm clears the mark, the pack decision enqueues through
	// EnqueuePackUrgent (accepted — the preferred lane had room), and the
	// fresh build publishes ahead of the buffered background work.
	packMu.Lock()
	packStarted = nil
	packMu.Unlock()
	// Two real background rows: the saturators must reach PackItem and PARK
	// on the gate (the unit seam's pin technique). A rowless id is a silent
	// GetItem-miss noop that never parks a worker — and workers idle-blocked
	// in the shared receive are never woken by an urgent send (queue.go's
	// bare shared receive; see the reported finding), so parking is what
	// makes the leg-4 dispatch deterministic.
	for _, bg := range []string{"ev-bg-0", "ev-bg-1"} {
		if err := w.st.PutItem(ctx, store.Item{
			ID: bg, ModuleID: "serial", LibraryID: libID, RelativePath: "Churn_Peak/bg.mkv",
			Document: json.RawMessage(`{}`), SchemaVersion: 1, Status: "active",
		}); err != nil {
			t.Fatalf("seed background row %s: %v", bg, err)
		}
	}
	saturated := false
	for i := 0; i < 4*16; i++ {
		if err := q.EnqueuePack(fmt.Sprintf("ev-bg-%d", i)); err != nil {
			saturated = true
			break
		}
	}
	if !saturated {
		t.Fatal("shared buffer never saturated — every background pack was accepted")
	}
	if err := q.EnqueuePack("ev-sweep-probe"); err == nil {
		t.Fatal("the sweep's plain enqueue was accepted while saturated — want the drop-on-full refusal")
	}
	play := evPlayClosure(w.st, q.EnqueuePackUrgent, sup)
	srv := httptest.NewServer(api.New(api.Deps{AdminToken: w.token, Store: w.st, Play: play}))
	t.Cleanup(srv.Close)
	req, err := http.NewRequest(http.MethodPost, srv.URL+"/api/v1/items/"+epID+"/play", bytes.NewBufferString(`{"retry":false}`))
	if err != nil {
		t.Fatalf("new play request: %v", err)
	}
	req.Header.Set("Authorization", "Bearer "+w.token)
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("POST /play: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusAccepted {
		t.Fatalf("POST /play status = %d, want 202 — the re-armed play must answer queued", resp.StatusCode)
	}
	var playBody struct {
		Queued bool `json:"queued"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&playBody); err != nil {
		t.Fatalf("decode play response: %v", err)
	}
	if !playBody.Queued {
		t.Fatal("body.queued = false, want true — the re-armed play enqueued through the preferred lane")
	}
	if sup.contains(epID) {
		t.Fatal("the mark survived the play — the re-arm never cleared the suppression")
	}

	// The fresh build: the worker takes the urgent task ahead of the shared
	// backlog, the real pack republishes under a FRESH nonce, and the
	// descriptor answers hls again over the served master+variant chain.
	openGate()
	// Dispatch before state: a stalled repack must first say whether the
	// urgent task ever reached the seam, then what the streams state became.
	// (The entry log resets before the saturation loop, so every entry from
	// here on is leg 4's; a probe task rides the same lane — if the probe
	// dispatches while epID never starts, the epID task was consumed before
	// PackItem.)
	// The dispatch discriminator (the test's own bounded poll): Pending
	// stays >0 iff the task died at the lease — the queue decrements the
	// counter only AFTER the lease succeeds, so a live-lease block returns
	// before it — and returns to 0 when the task was consumed after the
	// lease (the GetItem silent return).
	epStart := time.Now().Add(60 * time.Second)
	epEntered := false
	for time.Now().Before(epStart) {
		packMu.Lock()
		for _, id := range packStarted {
			if id == epID {
				epEntered = true
				break
			}
		}
		packMu.Unlock()
		if epEntered {
			break
		}
		time.Sleep(5 * time.Millisecond)
	}
	packMu.Lock()
	starts := append([]string(nil), packStarted...)
	packMu.Unlock()
	stats := q.Stats()
	if !epEntered {
		t.Fatalf("the play pack never reached the seam within 60s: starts=%v pending=%d inflight=%d", starts, stats.Pending, stats.InFlight)
	}
	streams4 := evAwaitStreamsState(ctx, t, w.st, epID, stream.StateComplete, 90*time.Second)
	nonce2, _ := streams4["nonce"].(string)
	if nonce2 == "" || nonce2 == nonce1 {
		t.Fatalf("fresh build nonce = %q (evicted build was %q) — the repack must publish a fresh build", nonce2, nonce1)
	}
	build2 := filepath.Join(w.root, epID, nonce2)
	if info, err := os.Stat(build2); err != nil || !info.IsDir() {
		t.Fatalf("fresh build missing on disk at %s: %v", build2, err)
	}
	if evDirSize(build2) <= 0 {
		t.Fatalf("fresh build at %s is empty", build2)
	}
	desc := pbDescriptor(t, w, epID)
	if desc.Mode != "hls" || desc.State != "complete" {
		t.Fatalf("descriptor after repack = mode %q state %q, want hls/complete", desc.Mode, desc.State)
	}
	assertPlayable(t, w, desc.PlayURL)
}
